package com.bank.ratealgo;

// Fixed window: simple; allows up to ~2x burst at the boundary.
public class FixedWindowLimiter implements RateLimiter {
    private final int limit;
    private final long windowMillis;
    private long windowStart = -1;
    private int count = 0;

    public FixedWindowLimiter(int limit, long windowMillis) {
        this.limit = limit; this.windowMillis = windowMillis;
    }

    @Override public synchronized boolean allow(long now) {
        if (windowStart < 0 || now - windowStart >= windowMillis) {
            windowStart = now; count = 0;      // abrupt reset → boundary burst
        }
        if (count < limit) { count++; return true; }
        return false;
    }
    @Override public String name() { return "fixed-window"; }
}
