package com.bank.ratealgo;

// Sliding-window counter: blend current + previous window → smooth boundary, low memory.
public class SlidingWindowCounterLimiter implements RateLimiter {
    private final int limit;
    private final long windowMillis;
    private long currentWindowStart = -1;
    private int currentCount = 0;
    private int previousCount = 0;

    public SlidingWindowCounterLimiter(int limit, long windowMillis) {
        this.limit = limit; this.windowMillis = windowMillis;
    }

    @Override public synchronized boolean allow(long now) {
        if (currentWindowStart < 0) currentWindowStart = now;
        if (now - currentWindowStart >= windowMillis) {
            previousCount = currentCount;      // roll window forward
            currentCount = 0;
            currentWindowStart = now;
        }
        double elapsed = (now - currentWindowStart) / (double) windowMillis;
        double weightedPrevious = previousCount * (1.0 - elapsed);
        double estimate = weightedPrevious + currentCount;   // smoothed rate
        if (estimate < limit) { currentCount++; return true; }
        return false;
    }
    @Override public String name() { return "sliding-window-counter"; }
}
