package com.bank.ratealgo;

// Token bucket: steady refill, allows controlled bursts up to capacity.
public class TokenBucketLimiter implements RateLimiter {
    private final double refillPerSecond;
    private final double capacity;
    private double tokens;
    private long lastRefillMillis = -1;

    public TokenBucketLimiter(double refillPerSecond, double capacity) {
        this.refillPerSecond = refillPerSecond; this.capacity = capacity;
        this.tokens = capacity;
    }

    @Override public synchronized boolean allow(long now) {
        if (lastRefillMillis < 0) lastRefillMillis = now;
        double elapsedSec = (now - lastRefillMillis) / 1000.0;
        tokens = Math.min(capacity, tokens + elapsedSec * refillPerSecond);
        lastRefillMillis = now;
        if (tokens >= 1.0) { tokens -= 1.0; return true; }
        return false;
    }
    @Override public String name() { return "token-bucket"; }
}
