package com.bank.ratealgo;

// Leaky bucket: queue drains at a CONSTANT rate; smooths bursty input.
public class LeakyBucketLimiter implements RateLimiter {
    private final double leakPerSecond;
    private final double capacity;
    private double queued;            // water currently in the bucket
    private long lastLeakMillis = -1;

    public LeakyBucketLimiter(double leakPerSecond, double capacity) {
        this.leakPerSecond = leakPerSecond; this.capacity = capacity;
    }

    @Override public synchronized boolean allow(long now) {
        if (lastLeakMillis < 0) lastLeakMillis = now;
        double elapsedSec = (now - lastLeakMillis) / 1000.0;
        queued = Math.max(0, queued - elapsedSec * leakPerSecond); // constant leak
        lastLeakMillis = now;
        if (queued + 1.0 <= capacity) { queued += 1.0; return true; } // add a drop
        return false;                                                  // overflow
    }
    @Override public String name() { return "leaky-bucket"; }
}
