package com.bank.ratealgo;

import java.util.List;
import java.util.logging.*;

public class RateAlgoDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(RateAlgoDemo.class.getName());

        int limit = 5;            // small numbers so the demo is readable
        long window = 1000;       // 1 second window

        // ADVERSARIAL boundary test: 5 requests at end of window, 5 at start of next.
        log.info("=== Boundary-burst test (limit=5/sec) ===");
        for (String algo : List.of("fixed", "sliding")) {
            RateLimiter limiter = algo.equals("fixed")
                    ? new FixedWindowLimiter(limit, window)
                    : new SlidingWindowCounterLimiter(limit, window);
            long base = 10_000;               // pretend window starts here
            int admitted = 0;
            // 5 requests at 999ms (end of window 1)
            for (int i = 0; i < 5; i++) if (limiter.allow(base + 999)) admitted++;
            // 5 requests at 1001ms (start of window 2) — only 2ms later!
            for (int i = 0; i < 5; i++) if (limiter.allow(base + 1001)) admitted++;
            log.info(limiter.name() + ": admitted " + admitted
                    + " in a 2ms span (fixed allows ~2x, sliding smooths)");
        }

        // BURST tolerance: token bucket vs leaky bucket on a sudden burst of 8.
        log.info("=== Burst test: 8 instant requests (refill/leak=5/sec, cap=5) ===");
        for (String algo : List.of("token", "leaky")) {
            RateLimiter limiter = algo.equals("token")
                    ? new TokenBucketLimiter(5, 5)
                    : new LeakyBucketLimiter(5, 5);
            long t = 20_000;
            int admitted = 0;
            for (int i = 0; i < 8; i++) if (limiter.allow(t)) admitted++; // all same instant
            log.info(limiter.name() + ": admitted " + admitted
                    + "/8 instant (token allows burst up to capacity, leaky caps to bucket)");
        }

        log.info("DISTRIBUTED: back ANY of these with a SHARED Redis counter (atomic Lua)");
        log.info("so N instances enforce ONE global limit, not N x limit.");
    }
}

